public boolean isValid(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.offer(')');
        } else if (c == '{') {
            stack.offer('}');
        } else if (c == '[') {
            stack.offer(']');
        } else {
            if (stack.isEmpty()) {
                return false;
            }
            if (stack.pollLast() != c) {
                return false;
            }
        }
    }
    return stack.isEmpty();
}

